{
  "implementation": "def solve(case):
    items = case["items"]
    req_fail = set(case.get("required_failure_items", []))
    unres_without = set(case.get("unresolved_without", []))

    def oracle(subset):
        subset_set = set(subset)
        if not unres_without.issubset(subset_set):
            return "UNRESOLVED"
        if req_fail.issubset(subset_set):
            return "FAIL"
        else:
            return "PASS"

    # initial test
    outcome = oracle(items)
    tests = 1
    config = list(items)
    g = 2

    while g <= len(config):
        n = g
        chunk_size = (len(config) + n - 1) // n
        found = False

        # test subsets
        for i in range(n):
            start = i * chunk_size
            end = min(start + chunk_size, len(config))
            subset = config[start:end]
            outcome = oracle(subset)
            tests += 1
            if outcome == "FAIL":
                config = subset
                g = 2
                found = True
                break

        if found:
            continue

        # test complements
        for i in range(n):
            start = i * chunk_size
            end = min(start + chunk_size, len(config))
            complement = config[:start] + config[end:]
            outcome = oracle(complement)
            tests += 1
            if outcome == "FAIL":
                config = complement
                g = 2
                found = True
                break

        if not found:
            if g == len(config):
                break
            g = min(g * 2, len(config))

    return {
        "minimal_failure": config,
        "outcome": "FAIL",
        "tests": tests
    }"
}
